create table user
(
    id               int auto_increment comment 'id'
        primary key,
    username         varchar(255)                          not null comment '用户名',
    age              int                                   null comment '年龄',
    password         varchar(255)                          not null comment '密码',
    nickname         varchar(255)                          null comment '昵称',
    address          varchar(255)                          null comment '地址',
    position         varchar(255)                          null comment '职位',
    email            varchar(255)                          null,
    user_pic         varchar(255)                          null comment '头像',
    create_time      timestamp   default CURRENT_TIMESTAMP null comment '创建时间',
    update_time      timestamp   default CURRENT_TIMESTAMP null on update CURRENT_TIMESTAMP comment '更新时间',
    institution      varchar(255)                          null,
    number           int                                   null comment '医生唯一标识',
    phone            varchar(255)                          null,
    room             varchar(255)                          null,
    role             tinyint     default 0                 not null comment '0:医生,1:管理员',
    status           varchar(10) default 'inactive'        not null comment '0:active,1:inactive,2:locked',
    is_authenticated tinyint     default 0                 null comment '1:is,0:is not',
    constraint user_8_pk
        unique (number),
    constraint user_8_pk_2
        unique (username)
)
    comment '用户表' collate = utf8mb4_bg_0900_ai_ci;

